/**
 * `yq-arduino` framing against protocol/vectors.json.
 *
 * The vectors are generated by protocol/generate_vectors.js, which shares no
 * code with src/ — so a pass here means the TypeScript agrees with an
 * independent writing of the spec, not with itself. The Arduino library is
 * tested against the same file.
 */
import { readFileSync } from "fs";
import { join } from "path";
import {
  ArduinoProtocol,
  FrameDecoder,
  cobsDecode,
  cobsEncode,
  crc16,
  encodeFrame,
  loadMsgpack,
  msgpackCodec,
} from "../../src";

interface Vectors {
  crc16: { cases: Array<{ input: string; crc: string }> };
  cobs: Array<{ name: string; decoded: string; encoded: string }>;
  frames: Array<{ name: string; message: unknown[]; body: string; crc: string; frame: string }>;
  invalidFrames: Array<{ name: string; frame: string; reason: string }>;
  byteStreams: Array<{ name: string; bytes: string; messages: string[]; dropped: number }>;
}

// Read rather than imported, so the file stays plain data and tsconfig stays as is.
const vectors: Vectors = JSON.parse(
  readFileSync(join(__dirname, "../../protocol/vectors.json"), "utf8")
);

const bytes = (text: string): Uint8Array =>
  Uint8Array.from(text.split(/\s+/).filter(Boolean).map((h) => parseInt(h, 16)));

const hex = (data: Uint8Array): string =>
  Array.from(data, (b) => b.toString(16).padStart(2, "0")).join(" ");

/** Turns the vectors' `{ $bin }` placeholders into bytes, and float32-rounds fractions. */
function materialise(value: any): any {
  if (Array.isArray(value)) return value.map(materialise);
  if (value && typeof value === "object") {
    if ("$bin" in value) return bytes(value.$bin);
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, materialise(v)])
    );
  }
  // The wire carries floats as float32, so a decoded 0.01 is not 0.01.
  if (typeof value === "number" && !Number.isInteger(value)) return Math.fround(value);
  return value;
}

beforeAll(() => loadMsgpack());

describe("CRC-16/CCITT-FALSE", () => {
  it.each(vectors.crc16.cases)("matches the vector for %j", (c) => {
    expect(crc16(bytes(c.input)).toString(16).padStart(4, "0")).toBe(c.crc);
  });
});

describe("COBS", () => {
  it.each(vectors.cobs)("encodes $name as the vector says", (c) => {
    expect(hex(cobsEncode(bytes(c.decoded)))).toBe(c.encoded);
  });

  it.each(vectors.cobs)("decodes $name back", (c) => {
    expect(hex(cobsDecode(bytes(c.encoded))!)).toBe(c.decoded);
  });

  it("never emits a zero", () => {
    for (const c of vectors.cobs) {
      expect(Array.from(cobsEncode(bytes(c.decoded)))).not.toContain(0);
    }
  });

  it("adds exactly one byte to a 254-byte payload", () => {
    const payload = Uint8Array.from({ length: 254 }, (_, i) => (i % 255) + 1);
    expect(cobsEncode(payload)).toHaveLength(255);
  });

  it("accepts the trailing empty block a naive encoder adds", () => {
    const payload = Uint8Array.from({ length: 254 }, (_, i) => i + 1);
    const naive = Uint8Array.of(0xff, ...payload, 0x01);
    expect(cobsDecode(naive)).toEqual(payload);
  });

  it("rejects a block that runs past the end", () => {
    expect(cobsDecode(bytes("05 01 02"))).toBeUndefined();
  });

  it("rejects a zero where a code byte belongs", () => {
    expect(cobsDecode(bytes("02 11 00 22"))).toBeUndefined();
  });

  it("round-trips every length around the block boundary", () => {
    for (const length of [0, 1, 253, 254, 255, 256, 507, 508, 509]) {
      const payload = Uint8Array.from({ length }, (_, i) => (i * 31) % 3 === 0 ? 0 : (i % 250) + 1);
      expect(cobsDecode(cobsEncode(payload))).toEqual(payload);
    }
  });
});

describe("frames", () => {
  it.each(vectors.frames)("$name: encodes to the vector's bytes", (f) => {
    const body = msgpackCodec.encode(materialise(f.message)) as Uint8Array;
    expect(hex(body)).toBe(f.body);
    expect(hex(encodeFrame(body))).toBe(f.frame);
  });

  it.each(vectors.frames)("$name: decodes to the vector's message", (f) => {
    const seen: Uint8Array[] = [];
    const decoder = new FrameDecoder((body) => seen.push(body));
    decoder.feed(bytes(f.frame));

    expect(seen).toHaveLength(1);
    expect(hex(seen[0])).toBe(f.body);
    expect(msgpackCodec.decode(seen[0])).toEqual(materialise(f.message));
    expect(decoder.stats.frames).toBe(1);
  });

  it("carries a maximum-size frame in 254 bytes", () => {
    const f = vectors.frames.find((x) => x.name === "data: maximum payload")!;
    expect(bytes(f.frame)).toHaveLength(254);
    // body + CRC is what the 254 limit measures.
    expect(bytes(f.body).length + 2).toBeLessThanOrEqual(254);
  });

  it("refuses a body that cannot fit", () => {
    expect(() => encodeFrame(new Uint8Array(253))).toThrow(RangeError);
    expect(() => encodeFrame(new Uint8Array(252))).not.toThrow();
  });

  it("honours a smaller limit", () => {
    expect(() => encodeFrame(new Uint8Array(63), 64)).toThrow(RangeError);
    expect(() => encodeFrame(new Uint8Array(62), 64)).not.toThrow();
  });
});

describe("FrameDecoder", () => {
  const byName = Object.fromEntries(vectors.frames.map((f) => [f.name, f]));

  function run(stream: string, chunkSizes: number[]) {
    const all = bytes(stream);
    const bodies: string[] = [];
    const decoder = new FrameDecoder((body) => bodies.push(hex(body)));
    let at = 0;
    for (let i = 0; at < all.length; i++) {
      const size = chunkSizes[i % chunkSizes.length];
      decoder.feed(all.subarray(at, at + size));
      at += size;
    }
    return { bodies, decoder };
  }

  describe.each(vectors.byteStreams)("$name", (s) => {
    const expected = s.messages.map((m) => byName[m].body);

    it.each([
      ["whole", [10_000]],
      ["byte by byte", [1]],
      ["in threes", [3]],
      ["ragged", [1, 7, 2, 11, 5]],
    ])("%s", (_label, sizes) => {
      const { bodies, decoder } = run(s.bytes, sizes as number[]);
      expect(bodies).toEqual(expected);
      const dropped = Object.values(decoder.stats.dropped).reduce((a, b) => a + b, 0);
      expect(dropped).toBe(s.dropped);
    });
  });

  it.each(vectors.invalidFrames.filter((f) => f.reason !== "shape"))(
    "drops $name",
    (f) => {
      const { bodies, decoder } = run(f.frame, [1000]);
      expect(bodies).toEqual([]);
      expect(decoder.stats.dropped[f.reason as "crc" | "cobs"]).toBe(1);
    }
  );

  it("passes a well-framed body that is not a message, for the layer above to judge", () => {
    const f = vectors.invalidFrames.find((x) => x.reason === "shape")!;
    const { bodies } = run(f.frame, [1000]);
    expect(bodies).toHaveLength(1);

    const session = new ArduinoProtocol();
    expect(session.decode(msgpackCodec.decode(bytes(bodies[0])))).toEqual([]);
    expect(session.stats.malformed).toBe(1);
  });

  it("drops an overlong frame and still reads the next one", () => {
    const seen: string[] = [];
    const decoder = new FrameDecoder((body) => seen.push(hex(body)));

    decoder.feed(new Uint8Array(400).fill(0x42));
    decoder.feed(Uint8Array.of(0));
    decoder.feed(bytes(byName["start"].frame));

    expect(decoder.stats.dropped.length).toBe(1);
    expect(seen).toEqual([byName["start"].body]);
  });

  it("flushes a half-received frame on a lone delimiter", () => {
    const seen: string[] = [];
    const decoder = new FrameDecoder((body) => seen.push(hex(body)));
    const frame = bytes(byName["start"].frame);

    decoder.feed(frame.subarray(0, 3)); // the board reset mid-frame
    decoder.feed(Uint8Array.of(0)); // the other side's flush
    decoder.feed(frame);

    expect(seen).toEqual([byName["start"].body]);
    expect(decoder.stats.dropped.cobs + decoder.stats.dropped.crc).toBe(1);
  });

  it("counts a body the message layer could not decode", () => {
    const decoder = new FrameDecoder(() => {});
    decoder.noteDecodeFailure();
    expect(decoder.stats.dropped.decode).toBe(1);
  });
});
